#!/usr/bin/env bash
# Generated by MiniMax M3.1 Flash without human creative authorship.
# SPDX-License-Identifier: LGPL-2.0-or-later
#
# Build the NSIS installer for Windows.
#
# Stages the built artifacts, the installer sources and the payload trees
# (python, node) into .tools/stage/, then runs makensis over the copy of
# installer/installer.nsi that lives there. The upstream installer/ directory
# is never modified.
#
# Usage (Git Bash on Windows):
#   bash tests/build_windows_installer.sh
#
# Run tests/build_windows_artifacts.sh first: the installer packages what
# that script builds.
set -euo pipefail
export MSYS_NO_PATHCONV=1

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TOOLS="$ROOT/.tools"
STAGE="$TOOLS/stage"
MAKENSIS="$(ls -1 "$TOOLS"/nsis/nsis-*/Bin/makensis.exe 2>/dev/null | head -1)"

if [[ ! -x "$MAKENSIS" ]]; then
  echo "ERROR: $MAKENSIS is missing; run tests/install_windows_toolchain.sh." >&2
  exit 1
fi

echo "=== Staging the installer payload ==="
cmd.exe //c "call $(cygpath -w "$ROOT/tests/stage_installer.bat")"

echo
echo "=== Running makensis ==="
cd "$STAGE/installer"
"$MAKENSIS" /NOCD /V4 /INPUTCHARSET UTF8 installer.nsi

echo
OUT="$(ls -1 "$STAGE/installer"/PIME-*-setup.exe 2>/dev/null | head -1)"
if [[ -z "$OUT" ]]; then
  echo "ERROR: no installer produced" >&2
  exit 1
fi
printf '==> installer: %s (%s bytes)\n' "$OUT" "$(stat -c%s "$OUT")"
